const visual = {
  prepare: function (input) {
    return [
      { kind: 'text', payload: '植物细胞结构示意图' },
      { kind: 'text', payload: '细胞壁' },
      { kind: 'text', payload: '细胞核' },
      { kind: 'text', payload: '液泡' }
    ];
  },
  render: function (input, metrics) {
    var W = input.viewport.widthDu;
    var H = input.viewport.heightDu;
    var s = Math.min(W / 800, H / 600);
    var ox = (W - 800 * s) / 2;
    var oy = (H - 600 * s) / 2;
    function X(x) { return ox + x * s; }
    function Y(y) { return oy + y * s; }
    function rectCmds(x, y, w, h, r) {
      var x0 = X(x), y0 = Y(y), x1 = X(x + w), y1 = Y(y + h), rr = r * s;
      return [
        ['M', x0 + rr, y0],
        ['L', x1 - rr, y0],
        ['Q', x1, y0, x1, y0 + rr],
        ['L', x1, y1 - rr],
        ['Q', x1, y1, x1 - rr, y1],
        ['L', x0 + rr, y1],
        ['Q', x0, y1, x0, y1 - rr],
        ['L', x0, y0 + rr],
        ['Q', x0, y0, x0 + rr, y0],
        ['Z']
      ];
    }
    function ellipseCmds(cx, cy, rx, ry) {
      var a = X(cx), b = Y(cy), u = rx * s, v = ry * s, k = 0.5522847498;
      return [
        ['M', a + u, b],
        ['C', a + u, b + k * v, a + k * u, b + v, a, b + v],
        ['C', a - k * u, b + v, a - u, b + k * v, a - u, b],
        ['C', a - u, b - k * v, a - k * u, b - v, a, b - v],
        ['C', a + k * u, b - v, a + u, b - k * v, a + u, b],
        ['Z']
      ];
    }
    function lineCmds(x1, y1, x2, y2) {
      return [['M', X(x1), Y(y1)], ['L', X(x2), Y(y2)]];
    }

    var paths = [
      { id: 'wall', commands: rectCmds(220, 120, 440, 380, 50) },
      { id: 'cytoplasm', commands: rectCmds(234, 134, 412, 352, 40) },
      { id: 'vacuoleRim', commands: ellipseCmds(470, 285, 152, 114) },
      { id: 'vacuole', commands: ellipseCmds(470, 285, 144, 106) },
      { id: 'nucleusRim', commands: visualSdk.circle(X(300), Y(400), 58 * s) },
      { id: 'nucleus', commands: visualSdk.circle(X(300), Y(400), 50 * s) },
      { id: 'nucleolus', commands: visualSdk.circle(X(292), Y(392), 16 * s) },
      { id: 'leaderWall', commands: lineCmds(176, 184, 227, 212) },
      { id: 'leaderNucleus', commands: lineCmds(158, 466, 252, 418) },
      { id: 'leaderVacuole', commands: lineCmds(696, 260, 596, 258) }
    ];

    return {
      schemaVersion: 1,
      sceneId: 'plant-cell-schematic',
      revision: input.revision,
      viewBox: { x: 0, y: 0, width: W, height: H },
      paths: paths,
      root: {
        type: 'group',
        children: [
          { type: 'path', pathId: 'wall', fill: '#6E9B4A', stroke: { width: 2 * s } },
          { type: 'path', pathId: 'cytoplasm', fill: '#F1F7DF', stroke: { width: 2 * s } },
          { type: 'path', pathId: 'vacuoleRim', fill: '#8FC2DE' },
          { type: 'path', pathId: 'vacuole', fill: '#CBE7F6' },
          { type: 'path', pathId: 'nucleusRim', fill: '#A98BC2' },
          { type: 'path', pathId: 'nucleus', fill: '#DCCCEA' },
          { type: 'path', pathId: 'nucleolus', fill: '#7C4F9B' },
          { type: 'path', pathId: 'leaderWall', fill: '#4B5B3E', stroke: { width: 2 * s, cap: 'round' } },
          { type: 'path', pathId: 'leaderNucleus', fill: '#4B5B3E', stroke: { width: 2 * s, cap: 'round' } },
          { type: 'path', pathId: 'leaderVacuole', fill: '#4B5B3E', stroke: { width: 2 * s, cap: 'round' } },
          { type: 'label', contentId: metrics[0].contentId, anchor: { x: X(400), y: Y(40) }, hAlign: 'center', vAlign: 'middle', color: '#2E3D26' },
          { type: 'label', contentId: metrics[1].contentId, anchor: { x: X(168), y: Y(180) }, hAlign: 'right', vAlign: 'middle', color: '#2E3D26' },
          { type: 'label', contentId: metrics[2].contentId, anchor: { x: X(150), y: Y(470) }, hAlign: 'right', vAlign: 'middle', color: '#2E3D26' },
          { type: 'label', contentId: metrics[3].contentId, anchor: { x: X(702), y: Y(258) }, hAlign: 'left', vAlign: 'middle', color: '#2E3D26' }
        ]
      }
    };
  }
};
